// Renders a WebP image generated by scripts/optimize-images.mjs (public/assets/<name>-<w>.webp).
export const assetUrl = (name, w) => `${import.meta.env.BASE_URL}assets/${name}-${w}.webp`

export default function ResponsiveImage({ name, widths, sizes, alt, width, height, priority = false, className, style, id }) {
  const max = Math.max(...widths)
  return (
    <img
      id={id}
      src={assetUrl(name, max)}
      srcSet={widths.map((w) => `${assetUrl(name, w)} ${w}w`).join(', ')}
      sizes={sizes}
      alt={alt}
      width={width}
      height={height}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : 'auto'}
      decoding="async"
      className={className}
      style={style}
    />
  )
}
